          id: 'f4', q: '공장 자동화와 AI는 무엇이 다른가요?', category: '시스템',
          a: `**자동화**와 **AI**는 대체 관계가 아니라, 자동화가 쌓아 둔 데이터 위에 AI가 얹히는 구조입니다.\n\n| 구분 | 자동화(PLC·설비 제어) | AI(예측·판단 지원) |\n|------|--------------------|------------------|\n| 판단 기준 | 사람이 정한 규칙·시퀀스 | 데이터로 학습한 확률 모델 |\n| 잘하는 일 | 정해진 동작의 정확한 반복 | 원인 후보 추론·사전 예측·문서 이해 |\n| 필요한 것 | 제어 로직·센서 배선 | **표준화된 데이터**와 결과 라벨 |\n| 우리 사례 | 프레스 자동 이송, 알람 인터록 | 경도 미달 사전 예측(AUC 0.91), 유사 도면 검색 |\n\n현재 한빛정밀은 **데이터 준비 단계(AI 준비도 레벨 2/5)** 로, 포스프레임 설비 태그 표준화(4,820개 중 62% 완료)가 선행 과제입니다.`,
